#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_blurA;
float4 amzSample_blurA(float2 uv) { return float4(amzt_blurA.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
uniform shader amzt_blurB;
float4 amzSample_blurB(float2 uv) { return float4(amzt_blurB.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
uniform shader amzt_blurC;
float4 amzSample_blurC(float2 uv) { return float4(amzt_blurC.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
uniform shader amzt_blurD;
float4 amzSample_blurD(float2 uv) { return float4(amzt_blurD.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/2.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_blurA(uv);if(tex==2) return amzSample_blurB(uv);if(tex==3) return amzSample_blurC(uv);if(tex==4) return amzSample_blurD(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_diffAmount;
uniform float amzp_diffRadius;
uniform float amzp_diffSoftness;
uniform float amzp_diffCharacter;
uniform float amzp_hlDiffusion;
uniform float amzp_hlThreshold;
uniform float amzp_hlWrap;
uniform float amzp_hlSaturation;
uniform float amzp_shDiffusion;
uniform float amzp_shThreshold;
uniform float amzp_shLift;
uniform float amzp_halStrength;
layout(color) uniform half4 amzp_halColor;
uniform float amzp_halRadius;
uniform float amzp_ortonStrength;
uniform float amzp_ortonGamma;
uniform float amzp_ortonContrast;
uniform float amzp_chromaDiff;
uniform float amzp_chromaAngle;
uniform float amzp_fogAmount;
layout(color) uniform half4 amzp_fogColor;
uniform float amzp_fogDensity;
uniform float amzp_fogHighlightBias;
uniform float amzp_dreamStrength;
uniform float amzp_dreamDesaturation;
uniform float amzp_dreamWarmth;
uniform float amzp_skinSmooth;
uniform float amzp_skinHueCenter;
uniform float amzp_skinHueRange;
uniform float amzp_skinDetail;
uniform float amzp_contrastRestore;
uniform float amzp_midtoneProtect;
uniform float amzp_blackPoint;
uniform float amzp_saturation;
uniform float amzp_warmth;
layout(color) uniform half4 amzp_diffTint;
uniform float amzp_diffTintStrength;
uniform float amzp_blendMode;
uniform float amzp_quality;
uniform float amzp_diffOnly;
uniform float amzp_ditherAmt;
uniform float amzp_globalMix;
    float3 toLinear(float3 s) {
        float3 lo = s / 12.92;
        float3 hi = pow((s + 0.055) / 1.055, float3(2.4));
        return mix(lo, hi, step(float3(0.04045), s));
    }
    float3 toSRGB(float3 l) {
        float3 lo = l * 12.92;
        float3 hi = 1.055 * pow(max(l, 0.0), float3(1.0 / 2.4)) - 0.055;
        return mix(lo, hi, step(float3(0.0031308), l));
    }
    float lum(float3 c) {
        return dot(c, float3(0.2126, 0.7152, 0.0722));
    }
    float3 rgb2hsl(float3 c) {
        float mx = max(c.r, max(c.g, c.b));
        float mn = min(c.r, min(c.g, c.b));
        float l = (mx + mn) * 0.5;
        float d = mx - mn;
        float s = 0.0;
        float h = 0.0;
        if (d > 0.00001) {
            s = (l > 0.5) ? d / max(2.0 - mx - mn, 0.00001) : d / max(mx + mn, 0.00001);
            if (mx == c.r) { h = (c.g - c.b) / d + (c.g < c.b ? 6.0 : 0.0); }
            else if (mx == c.g) { h = (c.b - c.r) / d + 2.0; }
            else { h = (c.r - c.g) / d + 4.0; }
            h /= 6.0;
        }
        return float3(h, s, l);
    }
    float h2r(float p, float q, float t) {
        if (t < 0.0) t += 1.0;
        if (t > 1.0) t -= 1.0;
        if (t < 1.0 / 6.0) return p + (q - p) * 6.0 * t;
        if (t < 0.5) return q;
        if (t < 2.0 / 3.0) return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
        return p;
    }
    float3 hsl2rgb(float3 c) {
        if (c.y < 0.00001) return float3(c.z);
        float q = (c.z < 0.5) ? c.z * (1.0 + c.y) : c.z + c.y - c.z * c.y;
        float p = 2.0 * c.z - q;
        return float3(h2r(p,q,c.x+1.0/3.0), h2r(p,q,c.x), h2r(p,q,c.x-1.0/3.0));
    }
    float getTaps(float q) {
        if (q < 1.5) return 10.0;
        if (q < 2.5) return 18.0;
        return 28.0;
    }
    float4 separableBlur(int tex, float2 uv, float2 dir, float radius, float taps) {
        if (radius <= 0.5) return amzTexture(tex, uv);
        float sigma = radius / 2.14596602;
        sigma = max(sigma, 0.00001);
        float baseCoeff = 1.0 / (sqrt(2.0 * 3.14159265359) * sigma);
        float decayRate = exp(-0.5 / (sigma * sigma));
        float decaySq = decayRate * decayRate;
        float4 acc = amzTexture(tex, uv) * baseCoeff;
        float wSum = baseCoeff;
        float coeff = baseCoeff;
        float decay = decayRate;
        for (float i = 1.0; i <= 256.0; i += 2.0) {
            if (i > taps) break;
            float p0 = i;
            float p1 = i + 1.0;
            coeff *= decay;
            wSum += 2.0 * coeff;
            float w0 = coeff;
            coeff *= decay;
            decay *= decaySq;
            wSum += 2.0 * coeff;
            float w1 = coeff;
            float wPair = w0 + w1;
            float oPair = (p0 * w0 + p1 * w1) / max(wPair, 0.00001);
            float2 uvA = clamp(uv - oPair * dir, 0.0, 1.0);
            float2 uvB = clamp(uv + oPair * dir, 0.0, 1.0);
            acc += amzTexture(tex, uvA) * wPair;
            acc += amzTexture(tex, uvB) * wPair;
        }
        return acc / max(wSum, 0.00001);
    }
    void amzRender() {
        float2 uv = amzScreenNorm();
        float taps = getTaps(float(int(amzp_quality)));
        float r1 = amzp_diffRadius * 0.5;
        float r2 = amzp_diffRadius * 1.5;
        if (amzPass == 0) {
            float2 dir = float2(1.0 / getTexSize((screen.zw/1.0)).x, 0.0);
            amzOutput = separableBlur(0, uv, dir, r1, taps);
            return;
        }
        if (amzPass == 1) {
            float2 dir = float2(0.0, 1.0 / getTexSize((screen.zw/2.0)).y);
            amzOutput = separableBlur(1, uv, dir, r1, taps);
            return;
        }
        if (amzPass == 2) {
            float2 dir = float2(1.0 / getTexSize((screen.zw/1.0)).x, 0.0);
            amzOutput = separableBlur(0, uv, dir, r2, taps);
            return;
        }
        if (amzPass == 3) {
            float2 dir = float2(0.0, 1.0 / getTexSize((screen.zw/2.0)).y);
            amzOutput = separableBlur(3, uv, dir, r2, taps);
            return;
        }
        float4 original = amzTexture(0, uv);
        float3 baseRGB = max(original.rgb, 0.0);
        float3 sharp = baseRGB;
        float3 softNarrow = max(amzTexture(2, uv).rgb, 0.0);
        float3 softWide = max(amzTexture(4, uv).rgb, 0.0);
        float3 baseLin = toLinear(baseRGB);
        float3 narrowLin = toLinear(softNarrow);
        float3 wideLin = toLinear(softWide);
        float baseLum = lum(baseLin);
        float narrowLum = lum(narrowLin);
        float wideLum = lum(wideLin);
        float3 diffused = mix(narrowLin, wideLin, amzp_diffSoftness);
        float diffLum = lum(diffused);
        float3 result = mix(baseLin, diffused, amzp_diffAmount * amzp_diffCharacter);
        float3 screenBlend = 1.0 - (1.0 - baseLin) * (1.0 - diffused * 0.5);
        result = mix(result, screenBlend, amzp_diffAmount * (1.0 - amzp_diffCharacter));
        if (amzp_hlDiffusion > 0.00001) {
            float hlMask = smoothstep(amzp_hlThreshold - 0.1, amzp_hlThreshold + 0.1, baseLum);
            float3 hlBlur = wideLin * hlMask;
            if (abs(amzp_hlSaturation - 1.0) > 0.00001) {
                float hlL = lum(hlBlur);
                hlBlur = mix(float3(hlL), hlBlur, amzp_hlSaturation);
            }
            result += hlBlur * amzp_hlDiffusion * 0.5;
            if (amzp_hlWrap > 0.00001) {
                float wrapMask = smoothstep(amzp_hlThreshold, amzp_hlThreshold + 0.3, baseLum);
                float3 wrapped = mix(result, wideLin, wrapMask * amzp_hlWrap * 0.3);
                result = wrapped;
            }
        }
        if (amzp_shDiffusion > 0.00001) {
            float shMask = smoothstep(amzp_shThreshold + 0.1, amzp_shThreshold - 0.1, baseLum);
            float3 shBlur = mix(baseLin, diffused, shMask * amzp_shDiffusion);
            result = mix(result, shBlur, shMask * amzp_shDiffusion * 0.5);
            if (amzp_shLift > 0.00001) {
                result += amzp_shLift * shMask;
            }
        }
        if (amzp_halStrength > 0.00001) {
            float3 halSource = mix(narrowLin, wideLin, clamp(amzp_halRadius - 1.0, 0.0, 1.0));
            float halLum = lum(halSource);
            float halMask = smoothstep(0.4, 0.8, halLum);
            float3 halation = halSource * amzp_halColor.rgb * halMask;
            result += halation * amzp_halStrength * 0.4;
        }
        if (amzp_ortonStrength > 0.00001) {
            float3 ortonBright = pow(max(baseLin, 0.0), float3(amzp_ortonGamma));
            float3 ortonBlur = diffused;
            float3 ortonMul = ortonBright * ortonBlur * 4.0;
            float3 ortonResult = mix(ortonBlur, ortonMul, amzp_ortonContrast);
            result = mix(result, ortonResult, amzp_ortonStrength * 0.5);
        }
        if (amzp_chromaDiff > 0.00001) {
            float cAng = amzp_chromaAngle * 3.14159265359 / 180.0;
            float2 cDir = float2(cos(cAng), sin(cAng));
            float2 cPx = 1.0 / getTexSize((screen.zw/2.0));
            float2 cOff = cDir * amzp_chromaDiff * 3.0 * cPx;
            float rCh = max(amzTexture(4, clamp(uv + cOff, 0.0, 1.0)).r, 0.0);
            float bCh = max(amzTexture(4, clamp(uv - cOff, 0.0, 1.0)).b, 0.0);
            float origR = result.r;
            float origB = result.b;
            result.r = mix(origR, toLinear(float3(rCh)).r, amzp_chromaDiff * 0.3);
            result.b = mix(origB, toLinear(float3(bCh)).b, amzp_chromaDiff * 0.3);
        }
        if (amzp_fogAmount > 0.00001) {
            float3 fogLin = toLinear(amzp_fogColor.rgb);
            float fogMask = mix(1.0, baseLum, amzp_fogHighlightBias);
            fogMask = pow(max(fogMask, 0.0), 1.0 + amzp_fogDensity * 2.0);
            result = mix(result, fogLin, amzp_fogAmount * fogMask * 0.3);
        }
        if (amzp_dreamStrength > 0.00001) {
            float3 dreamBase = mix(narrowLin, wideLin, 0.7);
            float dreamLum = lum(dreamBase);
            float3 dreamDesat = mix(dreamBase, float3(dreamLum), amzp_dreamDesaturation);
            if (abs(amzp_dreamWarmth) > 0.00001) {
                dreamDesat.r += amzp_dreamWarmth * 0.08;
                dreamDesat.b -= amzp_dreamWarmth * 0.05;
            }
            float3 dreamScreen = 1.0 - (1.0 - result) * (1.0 - dreamDesat * 0.4);
            result = mix(result, dreamScreen, amzp_dreamStrength * 0.6);
        }
        if (amzp_skinSmooth > 0.00001) {
            float3 skinTest = rgb2hsl(max(baseRGB, 0.0));
            float hueDist = abs(skinTest.x - amzp_skinHueCenter);
            hueDist = min(hueDist, 1.0 - hueDist);
            float skinMask = smoothstep(amzp_skinHueRange, amzp_skinHueRange * 0.3, hueDist);
            skinMask *= smoothstep(0.15, 0.35, skinTest.y);
            skinMask *= smoothstep(0.1, 0.3, skinTest.z) * (1.0 - smoothstep(0.8, 0.95, skinTest.z));
            if (skinMask > 0.00001) {
                float detailEdge = abs(baseLum - narrowLum) * 5.0;
                float detailPreserve = clamp(detailEdge / max(amzp_skinDetail, 0.00001), 0.0, 1.0);
                float smoothMask = skinMask * amzp_skinSmooth * (1.0 - detailPreserve);
                result = mix(result, narrowLin, smoothMask * 0.6);
            }
        }
        if (amzp_contrastRestore > 0.00001) {
            float rLum = lum(result);
            float contrast = (rLum - 0.5) * amzp_contrastRestore * 0.5;
            float midMask = 1.0 - abs(rLum - 0.5) * 2.0;
            midMask = pow(max(midMask, 0.0), 1.0 - amzp_midtoneProtect);
            result += contrast * (1.0 - midMask * amzp_midtoneProtect);
        }
        if (amzp_blackPoint > 0.00001) {
            result = max(result - amzp_blackPoint, 0.0) / max(1.0 - amzp_blackPoint, 0.00001);
        }
        if (abs(amzp_saturation - 1.0) > 0.00001) {
            float rL = lum(result);
            result = mix(float3(rL), result, amzp_saturation);
        }
        if (abs(amzp_warmth) > 0.00001) {
            result.r += amzp_warmth * 0.06;
            result.b -= amzp_warmth * 0.04;
        }
        if (amzp_diffTintStrength > 0.00001) {
            float3 tintLin = toLinear(amzp_diffTint.rgb);
            result = mix(result, result * tintLin, amzp_diffTintStrength);
        }
        float3 blendResult = result;
        float bm = float(int(amzp_blendMode));
        if (bm < 1.5) {
            blendResult = result;
        } else if (bm < 2.5) {
            blendResult = 1.0 - (1.0 - baseLin) * (1.0 - result * 0.5);
        } else if (bm < 3.5) {
            float3 bS = toSRGB(baseLin);
            float3 gS = toSRGB(clamp(result, 0.0, 1.0));
            float3 r;
            r.r = (gS.r<0.5) ? 2.0*bS.r*gS.r+bS.r*bS.r*(1.0-2.0*gS.r) : 2.0*bS.r*(1.0-gS.r)+sqrt(max(bS.r,0.0))*(2.0*gS.r-1.0);
            r.g = (gS.g<0.5) ? 2.0*bS.g*gS.g+bS.g*bS.g*(1.0-2.0*gS.g) : 2.0*bS.g*(1.0-gS.g)+sqrt(max(bS.g,0.0))*(2.0*gS.g-1.0);
            r.b = (gS.b<0.5) ? 2.0*bS.b*gS.b+bS.b*bS.b*(1.0-2.0*gS.b) : 2.0*bS.b*(1.0-gS.b)+sqrt(max(bS.b,0.0))*(2.0*gS.b-1.0);
            blendResult = toLinear(r);
        } else {
            float3 bS = toSRGB(baseLin);
            float3 gS = toSRGB(clamp(result, 0.0, 1.0));
            float3 r;
            r.r = (bS.r<0.5) ? 2.0*bS.r*gS.r : 1.0-2.0*(1.0-bS.r)*(1.0-gS.r);
            r.g = (bS.g<0.5) ? 2.0*bS.g*gS.g : 1.0-2.0*(1.0-bS.g)*(1.0-gS.g);
            r.b = (bS.b<0.5) ? 2.0*bS.b*gS.b : 1.0-2.0*(1.0-bS.b)*(1.0-gS.b);
            blendResult = toLinear(r);
        }
        float3 fin = toSRGB(max(blendResult, 0.0));
        if (amzp_ditherAmt > 0.00001) {
            float2 px = floor(getTexSize((screen.zw/1.0)) * uv);
            float n1 = fract(sin(dot(px, float2(12.9898, 78.233))) * 43758.5453);
            float n2 = fract(sin(dot(px, float2(24.123, 17.321))) * 12345.6789);
            float n3 = fract(sin(dot(px, float2(93.989, 67.345))) * 98765.4321);
            fin += (float3(n1, n2, n3) - 0.5) * amzp_ditherAmt;
        }
        if ((amzp_diffOnly>0.5)) {
            float3 diffOnlyRGB = toSRGB(max(result - baseLin, 0.0));
            amzOutput = float4(clamp(diffOnlyRGB, 0.0, 1.0), 1.0);
            return;
        }
        fin = mix(baseRGB, fin, amzp_globalMix);
        fin = clamp(fin, 0.0, 1.0);
        amzOutput = float4(fin, original.a);
    }

half4 main(float2 coord) { amzCoord=coord*2.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

